-- TypEase tenant isolation: database roles, grants, row-level security and
-- cross-tenant reference guards. Generated by scripts/prisma-to-sql.ts.

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'typease_app') THEN CREATE ROLE typease_app NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'typease_system') THEN CREATE ROLE typease_system NOLOGIN; END IF;
END $$;

-- Tenant / user context is set per transaction by the API (SET LOCAL via set_config).
CREATE OR REPLACE FUNCTION app_tenant_id() RETURNS uuid LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;
CREATE OR REPLACE FUNCTION app_user_id() RETURNS uuid LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

-- Blocks a row in tenant A from pointing at a row of tenant B through a foreign key.
-- SECURITY DEFINER so the lookup is not hidden by RLS.
CREATE OR REPLACE FUNCTION assert_same_tenant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  i int := 0;
  ref uuid;
  parent_tenant uuid;
  row_json jsonb := to_jsonb(NEW);
BEGIN
  WHILE i < TG_NARGS LOOP
    ref := (row_json ->> TG_ARGV[i])::uuid;
    IF ref IS NOT NULL THEN
      EXECUTE format('SELECT "tenantId" FROM %I WHERE id = $1', TG_ARGV[i + 1]) INTO parent_tenant USING ref;
      IF parent_tenant IS NOT NULL AND parent_tenant IS DISTINCT FROM (row_json ->> 'tenantId')::uuid THEN
        RAISE EXCEPTION 'cross-tenant reference blocked: %.% -> %', TG_TABLE_NAME, TG_ARGV[i], TG_ARGV[i + 1]
          USING ERRCODE = '23514';
      END IF;
    END IF;
    i := i + 2;
  END LOOP;
  RETURN NEW;
END $$;

GRANT USAGE ON SCHEMA public TO typease_app, typease_system;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO typease_app, typease_system;

-- users
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON "users" TO typease_system;
CREATE POLICY system_access ON "users" FOR ALL TO typease_system USING (true) WITH CHECK (true);
GRANT SELECT ("id", "email", "emailVerifiedAt", "phone", "phoneVerifiedAt", "fullName", "preferredLanguage", "platformRole", "status", "mfaEnabled", "lastLoginAt", "createdAt", "updatedAt", "deletedAt") ON "users" TO typease_app;
CREATE POLICY tenant_visible ON "users" FOR SELECT TO typease_app USING (id = app_user_id() OR EXISTS (SELECT 1 FROM "tenant_memberships" m WHERE m."userId" = "users".id AND m."tenantId" = app_tenant_id()));

